//! Emits `generated/model.rs`: one struct per complex type and one enum per
//! enumerated simple type of the merged model.

use std::fmt::Write as _;

use crate::merge::{FieldKind, MType, Model, Scalar};

pub fn emit(model: &Model, sources: &str) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "// @generated by xtask gen from {sources}; do not edit."
    );
    let _ = writeln!(
        out,
        "//! The typed GAEB model: every complex type of the schemas as a struct"
    );
    let _ = writeln!(out, "//! whose strings are spans into the document.\n");
    let _ = writeln!(out, "use crate::decimal::Decimal;");
    let _ = writeln!(out, "use crate::read::EnumValue;");
    let _ = writeln!(out, "use crate::span::Span;");
    let _ = writeln!(out, "use crate::tape::NodeId;\n");
    for e in model.enums.values() {
        let _ = writeln!(out, "#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]");
        let _ = writeln!(out, "pub enum {} {{", e.name);
        for (variant, _) in &e.variants {
            let _ = writeln!(out, "    {variant},");
        }
        let _ = writeln!(out, "}}\n");
        let _ = writeln!(out, "impl EnumValue for {} {{", e.name);
        let _ = writeln!(out, "    fn parse(text: &str) -> Option<Self> {{");
        let _ = writeln!(out, "        match text {{");
        for (variant, xml) in &e.variants {
            let _ = writeln!(out, "            \"{xml}\" => Some({}::{variant}),", e.name);
        }
        let _ = writeln!(out, "            _ => None,");
        let _ = writeln!(out, "        }}");
        let _ = writeln!(out, "    }}\n");
        let _ = writeln!(out, "    fn as_str(self) -> &'static str {{");
        let _ = writeln!(out, "        match self {{");
        for (variant, xml) in &e.variants {
            let _ = writeln!(out, "            {}::{variant} => \"{xml}\",", e.name);
        }
        let _ = writeln!(out, "        }}");
        let _ = writeln!(out, "    }}");
        let _ = writeln!(out, "}}\n");
    }
    for ty in model.types.values() {
        emit_struct(&mut out, ty);
    }
    out
}

fn emit_struct(out: &mut String, ty: &MType) {
    let _ = writeln!(out, "/// `{}`", ty.xsd);
    let _ = writeln!(out, "#[derive(Clone, Debug, Default)]");
    let _ = writeln!(out, "pub struct {} {{", ty.name);
    let _ = writeln!(out, "    pub node: NodeId,");
    if ty.text.is_some() {
        let _ = writeln!(out, "    pub text: Span,");
    }
    for a in &ty.attrs {
        let _ = writeln!(out, "    /// `@{}`", a.attribute);
        let _ = writeln!(
            out,
            "    pub {}: Option<{}>,",
            a.name,
            scalar_type(&a.scalar)
        );
    }
    for f in &ty.fields {
        let inner = match &f.kind {
            FieldKind::Complex(name) if f.boxed => format!("Box<{name}>"),
            FieldKind::Complex(name) => name.clone(),
            FieldKind::Scalar(s) => scalar_type(s).to_string(),
        };
        let _ = writeln!(out, "    /// `<{}>`", f.element);
        match f.many {
            true => {
                let _ = writeln!(out, "    pub {}: Vec<{inner}>,", f.name);
            }
            false => {
                let _ = writeln!(out, "    pub {}: Option<{inner}>,", f.name);
            }
        }
    }
    let _ = writeln!(
        out,
        "    /// Children the schema does not know, kept for writing back."
    );
    let _ = writeln!(out, "    pub extra: Vec<NodeId>,");
    let _ = writeln!(out, "}}\n");
}

pub fn scalar_type(s: &Scalar) -> &str {
    match s {
        Scalar::Span => "Span",
        Scalar::Decimal => "Decimal",
        Scalar::Integer => "i64",
        Scalar::Bool => "bool",
        Scalar::Enum(name) => name,
    }
}
